<?php require 'config.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['name']??'');$e=trim($_POST['email']??'');$ph=trim($_POST['phone']??'');$pw=$_POST['password']??'';if(!$n||!filter_var($e,FILTER_VALIDATE_EMAIL)||strlen($pw)<6)$err='Enter valid details. Password must be at least 6 characters.';else{try{$s=$pdo->prepare('INSERT INTO users(name,email,phone,password) VALUES(?,?,?,?)');$s->execute([$n,$e,$ph,password_hash($pw,PASSWORD_DEFAULT)]);go('user_login.php');}catch(Throwable $x){$err='That email is already registered.';}}}$page_title='Register';require 'includes/header.php';?><div class="form-wrap"><div class="form-card"><span class="eyebrow">DRIVER REGISTRATION</span><h1>Make parking yours.</h1><p>Create your free Parkora account.</p><?php if($err):?><div class="alert"><?=e($err)?></div><?php endif;?><form method="post"><div class="field"><label>Full name</label><input name="name" required></div><div class="two"><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Phone</label><input name="phone"></div></div><div class="field"><label>Password</label><input type="password" name="password" minlength="6" required></div><button class="btn primary" style="width:100%">Create account →</button></form></div></div><?php require 'includes/footer.php';?>
